#!/usr/bin/env python3
"""Publish only the reviewed unbound host source package, once into a new directory."""
import ast
import base64
import hashlib
import json
from pathlib import Path
import types

OUTPUT = '/Users/qianqi/Documents/Codex/2026-10-18/pocket4-razr60-ui/work/stock16-hepta-local-model-Root-v150-r1/followthrough-fc33-install-build-controller01'
PAYLOAD_PIN = {'bytes': 228591, 'sha256': '2d882bd13012936fcc56de91f29e14ee898811153e4334f95d1f4a8bc5ea2441'}
PAYLOAD_BASE64 = ''
HELPER_PIN = {'bytes': 34048, 'sha256': '766f6b933b4982088925669f327e0c7c2d03855b8c3f140052d7fbfd088d1b5f'}
FILE_COUNT = 27

def need(ok, reason):
    if not ok:
        raise ValueError(reason)

def pin(raw):
    return dict(bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())

def decode_payload():
    raw = base64.b64decode(PAYLOAD_BASE64, validate=True)
    need(pin(raw) == PAYLOAD_PIN, 'complete reviewed source payload bytes')
    value = json.loads(raw)
    need(type(value) is dict and len(value) == FILE_COUNT, 'complete exact source package payload')
    files = {name: base64.b64decode(encoded, validate=True) for name, encoded in value.items()}
    need(all(base64.b64encode(files[name]).decode() == encoded for name, encoded in value.items()),
         'exact full source payload encoding')
    helper = files['source/derive_component_build_inputs_UNBOUND.py']
    need(pin(helper) == HELPER_PIN, 'exact reviewed held-dirfd publisher owner')
    terminal = json.loads(files['DERIVATION.json'])
    need(terminal['output'] == OUTPUT and terminal['state'] == 'HOST_CONTROLLER_SOURCE_PACKAGE_PUBLISHED_ACTUAL_STAGES_UNBOUND'
         and terminal['file_count'] == FILE_COUNT and terminal['source_file_count'] == 5
         and all(terminal[k] is None for k in ('actual_case_inputs','actual_BUILD','actual_install','actual_READY')),
         'source publication only, all actual execution slots unbound')
    expected = {row['path'][len(OUTPUT)+1:]: row for row in terminal['files']}
    need(set(expected) == set(files)-{'DERIVATION.json'}, 'complete exact source payload membership')
    for name, row in expected.items():
        need(row['path'] == OUTPUT+'/'+name and pin(files[name]) == {k:row[k]for k in ('bytes','sha256')},
             'every reviewed full source byte pin')
        if name.endswith('.py'):
            compile(files[name], name, 'exec')
    for name, slot in (('derive_component_build_inputs_UNBOUND.py','FROZEN_INPUTS'),
                       ('derive_release_install_stages_UNBOUND.py','FROZEN_INPUTS'),
                       ('observe_p4_install_phase_UNBOUND.py','FROZEN_SPEC')):
        nodes = [n for n in ast.parse(files['source/'+name]).body if isinstance(n,ast.Assign)
                 and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id==slot]
        need(len(nodes)==1 and ast.literal_eval(nodes[0].value) is None, 'published actual slot remains None')
    module = types.ModuleType('reviewed_create_only_host_source_publisher')
    module.__file__ = OUTPUT+'/source/derive_component_build_inputs_UNBOUND.py'
    exec(compile(helper,module.__file__,'exec'),module.__dict__)
    return files, terminal, module

def main():
    files, terminal, module = decode_payload()
    output = Path(OUTPUT)
    need(output.is_absolute() and output.parent.resolve(strict=True)==output.parent,
         'exact existing host project parent')
    module.publish_material(output, files)
    row = dict(path=str(output/'DERIVATION.json'), **pin(files['DERIVATION.json']))
    need(module.HostReader()(row)==files['DERIVATION.json'], 'complete actual published terminal readback')
    print(json.dumps(dict(state=terminal['state'], source_package=terminal['source_package'],
        derivation=row, file_count=FILE_COUNT, source_file_count=5,
        phone_calls=0, actor_dispatches=0, BUILD_executed=False, actual_install=None, actual_READY=None), sort_keys=True))

if __name__=='__main__':
    main()
